def _split_pai_list(value):
    """Split one PAI field into addresses at commas outside quotes/angles."""
    pieces = []
    start = 0
    in_quote = False
    escaped = False
    in_angle = False
    for i, c in enumerate(value):
        if in_quote:
            if escaped:
                escaped = False
            elif c == "\\":
                escaped = True
            elif c == '"':
                in_quote = False
        else:
            if c == '"':
                in_quote = True
            elif c == "<":
                in_angle = True
            elif c == ">":
                in_angle = False
            elif c == "," and not in_angle:
                pieces.append(value[start:i])
                start = i + 1
    pieces.append(value[start:])
    result = []
    for piece in pieces:
        piece = piece.strip(" \t")
        if not piece:
            raise SIPFailure()
        result.append(piece)
    return result


def _char_is_ascii_printable_or_tab(c):
    return c == "\t" or (" " <= c <= "~")


def _check_header_line_chars(line):
    # A CR/LF inside a split line is a bare line ending, not a separator; all
    # controls other than HTAB, DEL, and non-ASCII are invalid too.
    for c in line:
        if c != "\t" and not (" " <= c <= "~"):
            raise SIPFailure()


def _check_body_chars(body):
    for c in body:
        if c == "\t" or c == "\r" or c == "\n":
            continue
        if not (" " <= c <= "~"):
            raise SIPFailure()


def _parse_header_fields(field_lines):
    """Unfold fields, returning [(lower-case expanded name, trimmed value)]."""
    if len(field_lines) > 512:
        raise SIPFailure()

    logical = []  # [lower-case original name, [value chunks]]
    for line in field_lines:
        if line and (line[0] == " " or line[0] == "\t"):
            if not logical:
                raise SIPFailure()
            logical[-1][1].append(line.lstrip(" \t"))
            continue

        colon = line.find(":")
        if colon < 0:
            raise SIPFailure()
        name_part = line[:colon].rstrip(" \t")
        if not name_part:
            raise SIPFailure()
        for c in name_part:
            if c not in TOKEN_CHARS:
                raise SIPFailure()
        value = line[colon + 1:]
        logical.append([name_part.lower(), [value]])
        if len(logical) > 128:
            raise SIPFailure()

    expanded = []
    for name, chunks in logical:
        # Each fold replaces CRLF plus its leading whitespace run with one SP.
        unfolded_value = " ".join(chunks).strip(" \t")
        canonical_name = COMPACT_NAMES.get(name, name)
        expanded.append((canonical_name, unfolded_value))
    return expanded


def _parse_cseq(value, method):
    m = CSEQ_RE.fullmatch(value)
    if m is None or m.group(2) != method:
        raise SIPFailure()
    canonical_number = m.group(1).lstrip("0")
    if not canonical_number:
        raise SIPFailure()
    if len(canonical_number) > 10:
        raise SIPFailure()
    if len(canonical_number) == 10 and canonical_number > "2147483647":
        raise SIPFailure()
    return canonical_number


def _parse_request(text):
    """Parse and fully syntax-validate one request.

    Returns a dictionary of all fields needed by policy and canonical output.
    Raises SIPFailure for any syntax problem.
    """
    if not isinstance(text, str) or len(text) > MAX_REQUEST_CHARS:
        raise SIPFailure()

    split_at = text.find("\r\n\r\n")
    if split_at < 0:
        raise SIPFailure()
    header_section = text[:split_at]
    body = text[split_at + 4:]

    _check_body_chars(body)

    lines = header_section.split("\r\n")
    for line in lines:
        _check_header_line_chars(line)
    request_line = lines[0]
    field_lines = lines[1:]

    request_parts = request_line.split(" ")
    if len(request_parts) != 3:
        raise SIPFailure()
    method, request_uri_text, version = request_parts
    if method not in ("INVITE", "MESSAGE"):
        raise SIPFailure()
    if version != "SIP/2.0":
        raise SIPFailure()
    request_uri, request_scheme = parse_uri(request_uri_text)
    if request_scheme != "sip":
        raise SIPFailure()

    fields = _parse_header_fields(field_lines)

    required_values = {name: [] for name in REQUIRED_SINGLETONS}
    optional_values = {name: [] for name in OPTIONAL_SINGLETONS}
    pai_field_values = []

    for name, value in fields:
        if name in required_values:
            required_values[name].append(value)
        elif name in optional_values:
            optional_values[name].append(value)
        elif name == PAI_NAME:
            pai_field_values.append(value)
        # Other fields have no semantics, as specified.

    for name in REQUIRED_SINGLETONS:
        if len(required_values[name]) != 1:
            raise SIPFailure()
    for name in OPTIONAL_SINGLETONS:
        if len(optional_values[name]) > 1:
            raise SIPFailure()

    from_value = required_values["from"][0]
    to_value = required_values["to"][0]
    call_id = required_values["call-id"][0]
    cseq_value = required_values["cseq"][0]
    content_length_value = required_values["content-length"][0]

    if not (1 <= len(call_id) <= 128):
        raise SIPFailure()
    for c in call_id:
        if c not in CALL_ID_CHARS:
            raise SIPFailure()

    cseq_number = _parse_cseq(cseq_value, method)

    if not DIGITS_RE.fullmatch(content_length_value):
        raise SIPFailure()
    canonical_content_length = content_length_value.lstrip("0") or "0"
    if canonical_content_length != str(len(body)):
        raise SIPFailure()

    content_type = None
    if optional_values["content-type"]:
        content_type = optional_values["content-type"][0]
        if not content_type:
            raise SIPFailure()
        for c in content_type:
            if not _char_is_ascii_printable_or_tab(c):
                raise SIPFailure()

    privacy = None
    if optional_values["privacy"]:
        privacy = optional_values["privacy"][0].lower()
        if privacy not in ("id", "none"):
            raise SIPFailure()

    (from_uri, from_scheme), from_tag = parse_from_or_to(from_value)
    (to_uri, to_scheme), to_tag = parse_from_or_to(to_value)

    ppi_parsed = None
    if optional_values["p-preferred-identity"]:
        ppi_parsed = parse_single_address(
            optional_values["p-preferred-identity"][0]
        )
        if ppi_parsed[0] == ANONYMOUS_URI:
            raise SIPFailure()

    rpid_parsed = None
    if optional_values["remote-party-id"]:
        rpid_parsed = parse_single_address(
            optional_values["remote-party-id"][0]
        )
        if rpid_parsed[0] == ANONYMOUS_URI:
            raise SIPFailure()

    pai_parsed = []
    for field_value in pai_field_values:
        for address_text in _split_pai_list(field_value):
            parsed_address = parse_single_address(address_text)
            if parsed_address[0] == ANONYMOUS_URI:
                raise SIPFailure()
            pai_parsed.append(parsed_address)

    if len(pai_parsed) > 2:
        raise SIPFailure()
    if len(pai_parsed) == 2:
        schemes = (pai_parsed[0][1], pai_parsed[1][1])
        if not ((schemes[0] == "sip" and schemes[1] == "tel") or
                (schemes[0] == "tel" and schemes[1] == "sip")):
            raise SIPFailure()

    return {
        "method": method,
        "request_uri": request_uri,
        "from_uri": from_uri,
        "from_scheme": from_scheme,
        "from_tag": from_tag,
        "to_uri": to_uri,
        "to_scheme": to_scheme,
        "to_tag": to_tag,
        "call_id": call_id,
        "cseq": cseq_number,
        "privacy": privacy,
        "content_type": content_type,
        "body": body,
        "ppi": ppi_parsed,
        "rpid": rpid_parsed,
        "pai": pai_parsed,
    }


def _identity_domain(identity):
    """Return the domain component of a canonical directory identity."""
    at = identity.rfind("@")
    if at < 0:
        return ""
    return identity[at + 1:]


def _lookup(alias_map, uri):
    return alias_map.get(uri)


def _authorize_local(parsed, gateway, account, alias_map):
    allowed = set(account.get("allow", ()))
    primary = account["primary"]
    allowed.add(primary)
    local_domains = set(gateway.get("local_domains", ()))

    def resolve_authorized(uri):
        identity = _lookup(alias_map, uri)
        if identity is None:
            raise IdentityFailure()
        if identity not in allowed:
            raise IdentityFailure()
        if _identity_domain(identity) not in local_domains:
            raise IdentityFailure()
        return identity

    from_identity = None
    if parsed["from_uri"] != ANONYMOUS_URI:
        from_identity = resolve_authorized(parsed["from_uri"])

    ppi_identity = None
    if parsed["ppi"] is not None:
        ppi_identity = resolve_authorized(parsed["ppi"][0])

    if ppi_identity is not None:
        selected = ppi_identity
    elif from_identity is not None:
        selected = from_identity
    else:
        selected = primary

    # The selected identity itself must always be allowed and locally hosted.
    if selected not in allowed:
        raise IdentityFailure()
    if _identity_domain(selected) not in local_domains:
        raise IdentityFailure()
    return selected


def _authorize_peer(parsed, gateway, peer_name, alias_map):
    authority = set(gateway.get("peers", {}).get(peer_name, ()))

    def resolve(uri):
        identity = _lookup(alias_map, uri)
        if identity is None:
            raise IdentityFailure()
        return identity

    if not parsed["pai"]:
        # The caller normally handles this as unauthenticated; keep the
        # invariant explicit for safety.
        raise IdentityFailure()

    asserted = None
    for address in parsed["pai"]:
        identity = resolve(address[0])
        if asserted is None:
            asserted = identity
        elif identity != asserted:
            raise IdentityFailure()

    if asserted is None:
        raise IdentityFailure()
    if _identity_domain(asserted) not in authority:
        raise IdentityFailure()

    if parsed["from_uri"] != ANONYMOUS_URI:
        if resolve(parsed["from_uri"]) != asserted:
            raise IdentityFailure()
    if parsed["ppi"] is not None:
        if resolve(parsed["ppi"][0]) != asserted:
            raise IdentityFailure()
    if parsed["rpid"] is not None:
        if resolve(parsed["rpid"][0]) != asserted:
            raise IdentityFailure()
    return asserted


def _build_wire(parsed, identity, private, trusted_out):
    from_uri = ANONYMOUS_URI if private else identity
    from_lines = "From: <" + from_uri + ">"
    if parsed["from_tag"] is not None:
        from_lines += ";tag=" + parsed["from_tag"]

    to_lines = "To: <" + parsed["to_uri"] + ">"
    if parsed["to_tag"] is not None:
        to_lines += ";tag=" + parsed["to_tag"]

    lines = [
        parsed["method"] + " " + parsed["request_uri"] + " SIP/2.0",
        from_lines,
        to_lines,
        "Call-ID: " + parsed["call_id"],
        "CSeq: " + parsed["cseq"] + " " + parsed["method"],
        "Privacy: " + ("id" if private else "none"),
    ]

    if (not private) or trusted_out:
        lines.append("P-Asserted-Identity: <" + identity + ">")
    if parsed["content_type"] is not None:
        lines.append("Content-Type: " + parsed["content_type"])
    lines.append("Content-Length: " + str(len(parsed["body"])))

    return "\r\n".join(lines) + "\r\n\r\n" + parsed["body"]


def _build_alias_map(directory):
    alias_map = {}
    for canonical, aliases in directory.items():
        alias_map[canonical] = canonical
        for alias in aliases:
            alias_map[alias] = canonical
    return alias_map


